"""Bounded exact-structure prototype for fixed-spin pion partial-wave masters.

This module does not replace production projection or discard coefficients.
Its recurrence is exact over the supplied scalar field; interval inputs give
enclosures and expose, rather than suppress, recurrence amplification.
"""
from fractions import Fraction as F
from math import comb

from .amplitudes import basis_labels


def reconstruct_moments(J,H,s,ell):
    """Recover M[n,m] from J[n]=M[n,0], H[n]=M[n,1], n=1..N."""
    J,H=list(J),list(H);N=len(J)
    if not N or len(H)!=N or not isinstance(ell,int) or ell<0:
        raise ValueError('Matching nonempty master edges and nonnegative integer spin required')
    epsilon=-1 if ell%2 else 1
    zero=J[0]*0;one=zero+1
    matrix=[[zero for _ in range(N+1)] for _ in range(N+1)]
    matrix[0][0]=one/2 if ell==0 else zero
    if epsilon==-1:
        compatible=H[0].contains(0) if hasattr(H[0],'contains') else H[0]==0
        if not compatible:raise ValueError('Odd-spin diagonal H1 must enclose zero')
    for n in range(1,N+1):
        matrix[n][0]=J[n-1];matrix[0][n]=epsilon*J[n-1]
        matrix[n][1]=H[n-1];matrix[1][n]=epsilon*H[n-1]
    if epsilon==-1:matrix[1][1]=zero
    a=2*(s+4)/(s-4);b=4*(s+12)/(s-4)
    for n in range(2,N+1):
        for m in range(2,n+1):
            if epsilon==-1 and n==m:
                value=zero
            else:
                value=-(matrix[n-2][m-2]+matrix[n][m-2]+matrix[n-2][m]
                    +a*(matrix[n-1][m-2]+matrix[n-2][m-1]+matrix[n][m-1]+matrix[n-1][m])
                    +b*matrix[n-1][m-1])
            matrix[n][m]=value;matrix[m][n]=epsilon*value
    return matrix


def assemble_isospin_row(moments,zs,degree,ell,isospin,phase_powers=None):
    """Assemble exactly the repository's full tensor-product source basis."""
    if len(moments)!=degree+1 or any(len(row)!=degree+1 for row in moments):
        raise ValueError('Moment matrix shape does not match degree')
    if isospin not in (0,1,2):raise ValueError('Isospin must be0,1,2')
    epsilon=-1 if ell%2 else 1;constant=moments[0][0];zero=constant*0
    if ell%2!=(isospin==1):return [zs*0 for _ in basis_labels(degree)]
    powers=[zs*0+1] if phase_powers is None else list(phase_powers)
    if phase_powers is None:
        for _ in range(degree):powers.append(powers[-1]*zs)
    elif len(powers)!=degree+1:raise ValueError('Phase-power count does not match degree')
    row=[]
    for kind,n,m in basis_labels(degree):
        if kind=='constant':A=B=constant
        elif kind=='single_s':A=powers[n]*constant;B=moments[n][0]
        elif kind=='single_tu':A=(1+epsilon)*moments[n][0];B=powers[n]*constant+epsilon*moments[n][0]
        elif kind=='double_s_tu':
            A=(1+epsilon)*powers[n]*moments[m][0]
            B=powers[m]*moments[n][0]+moments[n][m]
        elif kind=='double_tu':
            A=(1+epsilon)*moments[n][m]/2
            B=epsilon*(powers[n]*moments[m][0]+powers[m]*moments[n][0])/2
        else:raise ValueError('Unknown basis label')
        row.append(3*A+(1+epsilon)*B if isospin==0 else
                   ((1-epsilon)*B if isospin==1 else (1+epsilon)*B))
    return row


def laurent_legendre_coefficients(s,ell):
    """Exact dict exponent->coefficient for P_ell(1+32/d*(u^-1-u^-2))."""
    if not isinstance(ell,int) or ell<0:raise ValueError('Nonnegative integer spin required')
    s=F(s);z={0:F(1),-1:32/(s-4),-2:-32/(s-4)}
    previous={0:F(1)}
    if ell==0:return previous
    current=z
    for n in range(1,ell):
        product={}
        for i,a in z.items():
            for j,b in current.items():product[i+j]=product.get(i+j,F(0))+a*b
        following={i:(2*n+1)*v/(n+1) for i,v in product.items()}
        for i,v in previous.items():following[i]=following.get(i,F(0))-F(n,n+1)*v
        previous,current=current,{i:v for i,v in following.items() if v}
    return current


def K_combination_coefficients(s,ell,n):
    """Jn or Hn as a linear combination of K_r^0 or K_r^1 respectively."""
    if not isinstance(n,int) or n<0:raise ValueError('Nonnegative integer exponent required')
    output={}
    for a,value in laurent_legendre_coefficients(s,ell).items():
        for b in range(n+1):
            exponent=a+b
            output[exponent]=output.get(exponent,F(0))+value*comb(n,b)*(-1 if (n-b)%2 else 1)
    return {k:v for k,v in output.items() if v}


def elementary_K0(r,s,lower,log_lower):
    """First member of the universal K pair; supply u_min=4/(sqrt(s)+2)."""
    if not isinstance(r,int):raise ValueError('An integer exponent is required')
    if r==1:return 8/(s-4)*(2/lower-2+log_lower)
    if r==2:return 8/(s-4)*(lower-1-2*log_lower)
    return 8/(s-4)*(2*(1-lower**(r-2))/(r-2)-(1-lower**(r-1))/(r-1))
